import {createHash} from 'node:crypto';import {readFile,writeFile} from 'node:fs/promises';import {resolve} from 'node:path';import {pathToFileURL} from 'node:url';const root=process.argv[2];if(!root)throw Error('Pass the pinned Cubistry checkout');const file=resolve(root,'src/apps/calendar7/names-plasticity.ts');const hash=createHash('sha256').update(await readFile(file)).digest('hex');if(hash!=='ed21d7b72c1301c48dec7c75fdaf6a6a50dbf406c9ebf47063893163b81a79b1')throw Error('Source hash mismatch');const source=await import(pathToFileURL(file));const cases=[0,.6,1].map(p=>({p,parts:source.plasticityParts(p),gain:source.plasticityGain(p,true),floorFactor:source.floorOpacityFactor(source.plasticityParts(p).shadowStrength),roughness:source.NAMES_ROUGHNESS,clearcoat:source.NAMES_CLEARCOAT}));await writeFile('packages/viewer/test/fixtures/cubistry-names-plasticity.json',JSON.stringify({revision:'efafcc1d97687eccea0cde87a230f447ce1b6c66',sourceHash:hash,cases},null,2)+'\n');
